import{_ as p,a0 as l,w as r,s as o,ao as h,I as n,x as a,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Bash 基礎知識系列 #6：處理字符串操作 | LCTT x X-CMD","titleTemplate":false,"description":"Bash 基礎知識系列 #6：處理字符串操作 | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bash 基礎知識系列 #6：處理字符串操作 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bash 基礎知識系列 #6：處理字符串操作 | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230717.0 ⭐️⭐️ Bash Basics Series 6 Handling String Operations","title":"Bash 基礎知識系列 #6：處理字符串操作","tag":"202307","desc":""},"relativePath":"202307/20230717.0 ⭐️⭐️ Bash Basics Series 6 Handling String Operations.md","filePath":"[post].md"}'),d={name:"202307/20230717.0 ⭐️⭐️ Bash Basics Series 6 Handling String Operations.md"};function g(b,s,c,u,k,m){const t=l("Link");return r(),o("div",null,[s[15]||(s[15]=h(`<h1 id="bash-基礎知識系列-6-處理字符串操作" tabindex="-1">Bash 基礎知識系列 #6：處理字符串操作 <a class="header-anchor" href="#bash-基礎知識系列-6-處理字符串操作" aria-label="Permalink to “Bash 基礎知識系列 #6：處理字符串操作”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202307/30/090030gvm6pgutlvzll4zg.jpg" alt=""></p><p>在大多數編程語言中，你都會找到字符串數據類型。字符串基本上是一組字符。</p><p>但 Bash shell 有所不同。字符串沒有單獨的數據類型。這裏一切都是變量。</p><p>但這並不意味着你不能像在 C 和其他編程語言中那樣處理字符串。</p><p>在 Bash Shell 中可以查找子字符串、替換子字符串、連接字符串以及更多字符串操作。</p><p>在 Bash 基礎知識系列的這一部分中，你將學習基本的字符串操作。</p><h3 id="在-bash-中獲取字符串長度" tabindex="-1">在 Bash 中獲取字符串長度 <a class="header-anchor" href="#在-bash-中獲取字符串長度" aria-label="Permalink to “在 Bash 中獲取字符串長度”">​</a></h3><p>讓我們從最簡單的選項開始。也就是獲取字符串的長度。這很簡單：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\${#string}</span></span></code></pre></div><p>讓我們在示例中使用它。</p><p><img src="https://itsfoss.com/content/images/2023/07/bash-string-length-example.png" alt="Example of getting string length in bash"></p><p>正如你所看到的，第二個示例中有兩個單詞，但由於它用引號引起來，因此它被視為單個單詞。連空格都算作一個字符。</p><h3 id="在-bash-中連接字符串" tabindex="-1">在 Bash 中連接字符串 <a class="header-anchor" href="#在-bash-中連接字符串" aria-label="Permalink to “在 Bash 中連接字符串”">​</a></h3><p>用技術術語來説是字符串 <ruby>連接<rt>concatenation</rt></ruby>，這是 Bash 中最簡單的字符串操作之一。</p><p>你只需像這樣一個接一個地使用字符串變量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>str3=$str1$str2</span></span></code></pre></div><p>還能比這更簡單嗎？我覺得不能。</p><p>讓我們看一個例子。這是我的示例腳本，名為 <code>join.sh</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>read -p &quot;Enter first string: &quot; str1</span></span>
<span class="line"><span>read -p &quot;Enter second string: &quot; str2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>joined=$str1$str2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;The joined string is: $joined&quot;</span></span></code></pre></div><p>以下是該腳本的運行示例：</p><p><img src="https://itsfoss.com/content/images/2023/07/join-strings-bash.png" alt="Join two strings in bash"></p><h3 id="在-bash-中提取子字符串" tabindex="-1">在 Bash 中提取子字符串 <a class="header-anchor" href="#在-bash-中提取子字符串" aria-label="Permalink to “在 Bash 中提取子字符串”">​</a></h3><p>假設你有一個包含多個字符的大字符串，並且你想要提取其中的一部分。</p><p>要提取子字符串，需要指定主字符串、子字符串的起始位置和子字符串的長度，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\${string:$pos:$len}</span></span></code></pre></div><blockquote><p>💡 和數組一樣，字符串中的定位也是從 0 開始。</p></blockquote><p>這是一個例子：</p><p><img src="https://itsfoss.com/content/images/2023/07/extract-substring-bash.png" alt="Extracting substring in bash"></p><p>即使你指定的子字符串長度大於字符串長度，它也只會到達字符串末尾。</p><h3 id="替換-bash-中的子字符串" tabindex="-1">替換 Bash 中的子字符串 <a class="header-anchor" href="#替換-bash-中的子字符串" aria-label="Permalink to “替換 Bash 中的子字符串”">​</a></h3><p>假設你有一個大字符串，並且你想用另一個字符串替換其中的一部分。</p><p>在這種情況下，你可以使用這種語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\${string/substr1/substr2}</span></span></code></pre></div><blockquote><p>✋ 只有第一次出現的子字符串才會以這種方式替換。如果要替換所有出現的地方，請使用 <code>\${string//substr1/substr2}</code></p></blockquote><p>這是一個例子：</p><p><img src="https://itsfoss.com/content/images/2023/07/replace-substring-bash.png" alt="Replace substring in bash"></p><p>正如你在上面看到的，“good” 一詞被替換為 “best”。我將替換的字符串保存到同一字符串中以更改原始字符串。</p><blockquote><p>💡 如果未找到子字符串，則不會替換任何內容。它不會導致錯誤。</p></blockquote><h3 id="在-bash-中刪除子字符串" tabindex="-1">在 Bash 中刪除子字符串 <a class="header-anchor" href="#在-bash-中刪除子字符串" aria-label="Permalink to “在 Bash 中刪除子字符串”">​</a></h3><p>我們來談談刪除子字符串。假設你要刪除字符串的一部分。在這種情況下，只需將子字符串提供給主字符串，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\${string/substring}</span></span></code></pre></div><blockquote><p>✋ 通過這種方式，僅刪除第一次出現的子字符串。如果要刪除所有出現的內容，請使用 <code>\${string//substr}</code></p></blockquote><p>如果找到子字符串，則將從字符串中刪除它。</p><p>讓我們通過一個例子來看看。</p><p><img src="https://itsfoss.com/content/images/2023/07/bash-delete-substring.png" alt="Delete substring in bash"></p><p>不用説，如果沒有找到子字符串，則不會刪除它。它不會導致錯誤。</p><h3 id="🏋️-練習時間" tabindex="-1">🏋️ 練習時間 <a class="header-anchor" href="#🏋️-練習時間" aria-label="Permalink to “🏋️ 練習時間”">​</a></h3><p>現在是你通過簡單練習來實踐字符串操作的時候了。</p><p><strong>練習 1</strong>：聲明一個字符串 “I am all wet”。現在通過用 “set” 替換單詞 “wet” 來更改此字符串。</p><p><strong>練習 2</strong>：創建一個字符串，以 <code>112-123-1234</code> 格式保存電話號碼。現在，你必須刪除所有 <code>-</code>。</p><p>這應該會給你一些在 Bash 中使用字符串的不錯的練習。在下一章中，你將學習如何在 Bash 中使用 <code>if-else</code> 語句。敬請關注。</p><p><em>（題圖：MJ/aa73b2c9-6d2f-42e2-972d-94fab56d30cc）</em></p><hr>`,54)),n("p",null,[s[1]||(s[1]=a("via: ",-1)),e(t,{href:"https://itsfoss.com/bash-strings/"},{default:i(()=>[...s[0]||(s[0]=[a("https://itsfoss.com/bash-strings/",-1)])]),_:1})]),n("p",null,[s[6]||(s[6]=a("作者：",-1)),e(t,{href:"https://itsfoss.com/author/abhishek/"},{default:i(()=>[...s[2]||(s[2]=[a("Abhishek Prakash",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(t,{href:"https://github.com/lkxed/"},{default:i(()=>[...s[3]||(s[3]=[a("lkxed",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(t,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(t,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const C=p(d,[["render",g]]);export{x as __pageData,C as default};
